@if($page === 'products')
<script>
const productSearchInput = document.querySelector('[placeholder="Cari produk..."]');
const productSection = productSearchInput?.closest('section');
const productRows = productSection ? [...productSection.querySelectorAll('.divide-y > div')] : [];
const categoryBar = productSearchInput?.parentElement?.nextElementSibling;
let activeProductCategory = 'Semua';

if (productSearchInput && categoryBar) {
    const productCategories = ['Semua', ...new Set(productRows.map((row) => row.querySelector('span.text-xs')?.textContent.trim()).filter(Boolean))];
    categoryBar.innerHTML = productCategories.map((category) => `<button type="button" data-product-category="${category}" class="rounded-xl px-4 py-2 text-xs font-semibold ${category === 'Semua' ? 'bg-[#FF7043] text-white' : 'bg-slate-50 text-slate-500'}">${category}</button>`).join('');

    const filterProducts = () => {
        const keyword = productSearchInput.value.trim().toLowerCase();
        productRows.forEach((row) => {
            const category = row.querySelector('span.text-xs')?.textContent.trim() || '';
            const matchesCategory = activeProductCategory === 'Semua' || category === activeProductCategory;
            const matchesSearch = row.textContent.toLowerCase().includes(keyword);
            row.classList.toggle('hidden', !matchesCategory || !matchesSearch);
        });
    };

    categoryBar.addEventListener('click', (event) => {
        const button = event.target.closest('[data-product-category]');
        if (!button) return;
        activeProductCategory = button.dataset.productCategory;
        categoryBar.querySelectorAll('[data-product-category]').forEach((categoryButton) => {
            const isActive = categoryButton === button;
            categoryButton.classList.toggle('bg-[#FF7043]', isActive);
            categoryButton.classList.toggle('text-white', isActive);
            categoryButton.classList.toggle('bg-slate-50', !isActive);
            categoryButton.classList.toggle('text-slate-500', !isActive);
        });
        filterProducts();
    });

    productSearchInput.addEventListener('input', filterProducts);
}
</script>
